conditions_override_check" CHECK ("override" IN ('auto','closed','open')), CONSTRAINT "time_conditions_toggle_number_check" CHECK ((toggle_number ~ '^([0-9]{1,4})?$'::text)), CONSTRAINT "time_conditions_schedule_id_fkey" FOREIGN KEY ("schedule_id") REFERENCES "schedules" ("id") ON DELETE RESTRICT);

