ng_check" CHECK (((internal_dialing ->> 'mode'::text) = ANY (ARRAY['off'::text, 'patterns'::text, 'all'::text]))), CONSTRAINT "trunks_max_calls_check" CHECK ((max_calls >= 0)), CONSTRAINT "trunks_mode_check" CHECK ("mode" IN ('ip','registration')), CONSTRAINT "trunks_name_check" CHECK ((name ~ '^[A-Za-z0-9._-]{1,64}$'::text)), CONSTRAINT "trunks_options_interval_check" CHECK (((options_interval >= 5) AND (options_interval <= 3600))), CONSTRAINT "trunks_profile_check" CHECK ("profile" IN ('generic','sbc-peer')), CONSTRAINT "trunks_register_expires_check" CHECK (((register_expires >= 60) AND (register_expires <= 86400))), CONSTRAINT "trunks_reject_code_check" CHECK ((reject_code = ANY (ARRAY[603, 486]))), CONSTRAINT "trunks_session_timers_check" CHECK ("session_timers" IN ('default','off','on')), CONSTRAINT "trunks_srtp_check" CHECK ("srtp" IN ('off','optional','required')), CONSTRAINT "trunks_unknown_caller_action_check" CHECK ("unknown_caller_action" IN ('allow','block')));

