CREATE TABLE "msg_addresses" ("id" bigserial NOT NULL, "channel_id" bigint NOT NULL, "address" text NOT NULL, "address_key" text NOT NULL, "address_suffix" text DEFAULT ''::text NOT NULL, "label" text DEFAULT ''::text NOT NULL, "route_kind" text DEFAULT 'inbox'::text NOT NULL, "route_target" text DEFAULT ''::text NOT NULL, "optout_keywords" text[] DEFAULT '{stop,stopall,unsubscribe,cancel,end,quit}'::text[] NOT NULL, "help_text" text DEFAULT ''::text NOT NULL, "optout_text" text DEFAULT ''::text NOT NULL, "enabled" boolean DEFAULT true NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "sends_per_minute" integer DEFAULT 60 NOT NULL, "desk_phone_delivery" boolean DEFAULT false NOT NULL, "owner_extension_id" bigint, "schedule" jsonb DEFAULT '{}'::jsonb NOT NULL, "after_hours_action" text DEFAULT 'none'::text NOT NULL, "after_hours_text" text DEFAULT ''::text NOT NULL, "after_hours_route_kind" text DEFAULT 'inbox'::text NOT NULL, "after_hours_route_target" text DEFAULT ''::text NOT NULL, "first_contact_text" text DEFAULT ''::text NOT NULL, "ai_mode" text DEFAULT 'off'::text NOT NULL, "ai_redact" boolean DEFAULT true NOT NULL, "ai_disclosure" boolean DEFAULT true NOT NULL, "ai_disclosure_text" text DEFAULT 'This is an automated reply.'::text NOT NULL, "ai_holding_text" text DEFAULT ''::text NOT NULL, "ai_max_replies" integer DEFAULT 3 NOT NULL, "ai_hourly_cap" integer DEFAULT 60 NOT NULL, "ai_min_confidence" real DEFAULT 0.8 NOT NULL, "ai_auto_intents" text[] DEFAULT '{}'::text[] NOT NULL, "ai_handoff_words" text[] DEFAULT '{agent,human,person,representative}'::text[] NOT NULL, CONSTRAINT "msg_addresses_pkey" PRIMARY KEY ("id"), CONSTRAINT "msg_addresses_channel_id_address_key_key" UNIQUE ("channel_id", "address_key"), CONSTRAINT "msg_addresses_address_check" CHECK (((length(address) >= 2) AND (length(address) <= 64))), CONSTRAINT "msg_addresses_after_hours_action_check" CHECK ("after_hours_action" IN ('none','reply','route')), CONSTRAINT "msg_addresses_after_hours_route_kind_check" CHECK ("after_hours_route_kind" IN ('extension','inbox','queue','ring_group','user')), CONSTRAINT "msg_addresses_after_hours_text_check" CHECK ((length(after_hours_text) <= 480)), CONSTRAINT "msg_addresses_ai_disclosure_text_check" CHECK ((length(ai_disclosure_text) <= 160)), CONSTRAINT "msg_addresses_ai_holding_text_check" CHECK ((length(ai_holding_text) <= 480)), CONSTRAINT "msg_addresses_ai_hourly_cap_check" CHECK (((ai_hourly_cap >= 1) AND (ai_hourly_cap <= 1000))), CONSTRAINT "msg_addresses_ai_max_replies_check" CHECK (((ai_max_replies >= 1) AND (ai_max_replies <= 10))), CONSTRAINT "msg_addresses_ai_min_confidence_check" CHECK (((ai_min_confidence >= (0)::double precision) AND (ai_min_confidence <= (1)::double precision))), CONSTRAINT "msg_addresses_ai_mode_check" CHECK ("ai_mode" IN ('auto','draft','off','triage')), CONSTRAINT "msg_addresses_first_contact_text_check" CHECK ((length(first_contact_text) <= 480)), CONSTRAINT "msg_addresses_help_text_check" CHECK ((length(help_text) <= 480)), CONSTRAINT "msg_addresses_label_check" CHECK ((length(label) <= 100)), CONSTRAINT "msg_addresses_optout_text_check" CHECK ((length(optout_text) <= 480)), CONSTRAINT "msg_addresses_route_kind_check" CHECK ("route_kind" IN ('ai_triage','extension','inbox','queue','ring_group','user')), CONSTRAINT "msg_addresses_sends_per_minute_check" CHECK (((sends_per_minute >= 1) AND (sends_per_minute <= 600))), CONSTRAINT "msg_addresses_channel_id_fkey" FOREIGN KEY ("channel_id") REFERENCES "msg_channels" ("id") ON DELETE CASCADE, CONSTRAINT "msg_addresses_owner_extension_id_fkey" FOREIGN KEY ("owner_extension_id") REFERENCES "extensions" ("id") ON DELETE SET NULL);

CREATE TABLE "chat_sites" ("id" bigserial NOT NULL, "channel_id" bigint NOT NULL, "address_id" bigint NOT NULL, "site_key" text NOT NULL, "allowed_origins" text[] DEFAULT '{}'::text[] NOT NULL, "greeting" text DEFAULT ''::text NOT NULL, "accent" text DEFAULT '#2563eb'::text NOT NULL, "position" text DEFAULT 'right'::text NOT NULL, "collect" text DEFAULT 'off'::text NOT NULL, "offline_mode" text DEFAULT 'collect'::text NOT NULL, "privacy_url" text DEFAULT ''::text NOT NULL, "challenge" text DEFAULT 'pow'::text NOT NULL, "pow_bits" integer DEFAULT 16 NOT NULL, "turnstile_site_key" text DEFAULT ''::text NOT NULL, "turnstile_secret_enc" bytea, "strip_links" boolean DEFAULT false NOT NULL, "max_open_unassigned" integer DEFAULT 200 NOT NULL, "transcripts" boolean DEFAULT false NOT NULL, "retention_days" integer, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL, "attachments" boolean DEFAULT false NOT NULL, "logo_type" text DEFAULT ''::text NOT NULL, "logo_updated_at" timestamp with time zone, CONSTRAINT "chat_sites_pkey" PRIMARY KEY ("id"), CONSTRAINT "chat_sites_address_id_key" UNIQUE ("address_id"), CONSTRAINT "chat_sites_channel_id_key" UNIQUE ("channel_id"), CONSTRAINT "chat_sites_site_key_key" UNIQUE ("site_key"), CONSTRAINT "chat_sites_accent_check" CHECK ((accent ~ '^#[0-9a-fA-F]{6}$'::text)), CONSTRAINT "chat_sites_challenge_check" CHECK ("challenge" IN ('none','pow','turnstile')), CONSTRAINT "chat_sites_collect_check" CHECK ("collect" IN ('off','optional','required')), CONSTRAINT "chat_sites_greeting_check" CHECK ((length(greeting) <= 500)), CONSTRAINT "chat_sites_logo_type_check" CHECK ("logo_type" IN ('','image/gif','image/jpeg','image/png','image/webp')), CONSTRAINT "chat_sites_max_open_unassigned_check" CHECK (((max_open_unassigned >= 1) AND (max_open_unassigned <= 100000))), CONSTRAINT "chat_sites_offline_mode_check" CHECK ("offline_mode" IN ('collect','hidden')), CONSTRAINT "chat_sites_position_check" CHECK ("position" IN ('left','right')), CONSTRAINT "chat_sites_pow_bits_check" CHECK (((pow_bits >= 14) AND (pow_bits <= 22))), CONSTRAINT "chat_sites_privacy_url_check" CHECK ((length(privacy_url) <= 500)), CONSTRAINT "chat_sites_retention_days_check" CHECK (((retention_days >= 1) AND (retention_days <= 3650))), CONSTRAINT "chat_sites_site_key_check" CHECK ((site_key ~ '^[0-9a-f]{24}$'::text)), CONSTRAINT "chat_sites_turnstile_site_key_check" CHECK ((length(turnstile_site_key) <= 100)), CONSTRAINT "chat_sites_address_id_fkey" FOREIGN KEY ("address_id") REFERENCES "msg_addresses" ("id") ON DELETE CASCADE, CONSTRAINT "chat_sites_channel_id_fkey" FOREIGN KEY ("channel_id") REFERENCES "msg_channels" ("id") ON DELETE CASCADE);

