 CONSTRAINT "phones_model_check" CHECK (((length(model) >= 1) AND (length(model) <= 64))), CONSTRAINT "phones_prev_token_hash_check" CHECK ((length(prev_token_hash) = 32)), CONSTRAINT "phones_redirect_status_check" CHECK ((jsonb_typeof(redirect_status) = 'object'::text)), CONSTRAINT "phones_serial_check" CHECK (((length(serial) >= 1) AND (length(serial) <= 64))), CONSTRAINT "phones_sharing_role_check" CHECK ("sharing_role" IN ('guest','host')), CONSTRAINT "phones_side_key_check" CHECK ("side_key" IN ('alarm','none','ptt')), CONSTRAINT "phones_token_hash_check" CHECK ((length(token_hash) = 32)), CONSTRAINT "phones_vendor_check" CHECK ("vendor" IN ('fanvil','generic','grandstream','poly','snom','yealink')), CONSTRAINT "phones_device_id_fkey" FOREIGN KEY ("device_id") REFERENCES "devices" ("id") ON DELETE RESTRICT, CONSTRAINT "phones_group_id_fkey" FOREIGN KEY ("group_id") REFERENCES "phone_groups" ("id") ON DELETE SET NULL, CONSTRAINT "phones_location_id_fkey" FOREIGN KEY ("location_id") REFERENCES "locations" ("id") ON DELETE RESTRICT, CONSTRAINT "phones_ptt_channel_id_fkey" FOREIGN KEY ("ptt_channel_id") REFERENCES "multicast_channels" ("id") ON DELETE SET NULL, CONSTRAINT "phones_template_id_fkey" FOREIGN KEY ("template_id") REFERENCES "prov_templates" ("id") ON DELETE RESTRICT);

