CREATE FUNCTION "scep_revoke_removed_phone"() RETURNS trigger LANGUAGE "plpgsql" VOLATILE AS $momo$
BEGIN
    UPDATE scep_certificates SET revoked_at = now(), revoke_reason = 'phone_removed'
    WHERE phone_id = OLD.id AND revoked_at IS NULL;
    RETURN OLD;
END;
$momo$;

CREATE TRIGGER "phones_scep_revoke" BEFORE DELETE ON "phones" FOR EACH ROW EXECUTE FUNCTION scep_revoke_removed_phone();
